import osimport jsonimport shutilimport zipfilefrom pathlib import Pathfrom urllib.parse import quoteimport pandas as pdimport requestsTARGET_LIST = "ASTR502_Master_Target_List.csv"DATA_DIR = Path("data/exofop_spectra")DATA_DIR.mkdir(parents=True, exist_ok=True)CONNECT_TIMEOUT = 20READ_TIMEOUT = 300HEADERS = {"User-Agent": "Mozilla/5.0 (ASTR502 script)"}DEBUG = FalseSESSION = requests.Session()SESSION.headers.update(HEADERS)def get_with_retries(url, stream=False, retries=4, backoff=10):    """    Retries on timeouts/temporary failures.    backoff is seconds to wait, grows linearly.    """    for attempt in range(1, retries + 1):        try:            return SESSION.get(url, stream=stream, timeout=(CONNECT_TIMEOUT, READ_TIMEOUT))        except requests.exceptions.ReadTimeout:            print(f"[WARN] timeout (attempt {attempt}/{retries}) for {url}")        except requests.exceptions.ConnectionError:            print(f"[WARN] connection error (attempt {attempt}/{retries}) for {url}")        if attempt < retries:            import time            time.sleep(backoff * attempt)    return Nonedef gototicid(target_name: str) -> str | None:    url = f"https://exofop.ipac.caltech.edu/tess/gototicid.php?target={quote(target_name)}&json"    r = get_with_retries(url, stream=False)    if r is None:        return None    r.raise_for_status()    data = r.json()    if data.get("status") != "OK":        return None    tic = data.get("TIC")    if tic is None:        return None    return str(tic).strip()def download_filelist(tic: str) -> pd.DataFrame | None:    url = f"https://exofop.ipac.caltech.edu/tess/download_filelist.php?id={tic}&output=csv"    r = get_with_retries(url, stream=False)    if r is None:        return None    r.raise_for_status()    text = r.text.strip()    if not text or "ERROR" in text[:200].upper():        return None    from io import StringIO    df = pd.read_csv(StringIO(text))    df.columns = [c.strip() for c in df.columns]    return dfdef download_all_files_zip(tic: str, out_zip: Path) -> bool:    url = f"https://exofop.ipac.caltech.edu/tess/download_files_zip.php?id={tic}"    r = get_with_retries(url, stream=True)    if r is None:        return False    if r.status_code != 200:        return False    out_zip.parent.mkdir(parents=True, exist_ok=True)    try:        with r:            with open(out_zip, "wb") as f:                for chunk in r.iter_content(chunk_size=1024 * 256):                    if chunk:                        f.write(chunk)    except requests.exceptions.ReadTimeout:        # If it times out mid-stream, treat as failed and let caller continue        try:            if out_zip.exists():                out_zip.unlink()        except OSError:            pass        return False    return out_zip.exists() and out_zip.stat().st_size > 0def extract_zip(zip_path: Path, out_dir: Path) -> None:    out_dir.mkdir(parents=True, exist_ok=True)    with zipfile.ZipFile(zip_path, "r") as z:        z.extractall(out_dir)def keep_only_selected_files(folder: Path, allowed_names: set[str]) -> int:    kept = 0    for p in folder.rglob("*"):        if p.is_file():            if p.name in allowed_names:                kept += 1            else:                p.unlink()    for p in sorted(folder.rglob("*"), reverse=True):        if p.is_dir():            try:                p.rmdir()            except OSError:                pass    return kepttic_cache = {}def main():    targets = pd.read_csv(TARGET_LIST)    name_cols = [c for c in ["hostname", "pl_name"] if c in targets.columns]    if not name_cols:        raise ValueError(f"No hostname or pl_name columns found in {TARGET_LIST}.")    for _, row in targets.iterrows():        target_name = None        for c in name_cols:            val = row.get(c)            if isinstance(val, str) and val.strip():                target_name = val.strip()                break        if not target_name:            continue              tic = tic_cache.get(target_name)        if tic is None:            tic = gototicid(target_name)            tic_cache[target_name] = tic        if tic is None:           print(f"[NONE] {target_name}: no TIC match in ExoFOP.")           continue              filelist = download_filelist(tic)        if filelist is None or filelist.empty:            print(f"[NONE] TIC {tic}: no files or unexpected filelist format.")            continue        type_col = "Type" if "Type" in filelist.columns else None        name_col = "File Name" if "File Name" in filelist.columns else None        if type_col is None or name_col is None:            print(f"[NONE] TIC {tic}: filelist missing Type/File Name columns.")            if DEBUG:                print("Columns returned:", list(filelist.columns))            continue        spectra = filelist[            (filelist[type_col].astype(str).str.strip() == "Spectrum")            & (filelist[name_col].astype(str).str.lower().str.endswith(".fits"))        ]        if spectra.empty:            print(f"[NONE] TIC {tic}: no Spectrum .fits available.")            if DEBUG:                print("File types present:", sorted(filelist[type_col].astype(str).str.strip().unique()))                print("Example filenames:", filelist[name_col].head(10).tolist())            continue        target_dir = DATA_DIR / f"TIC{tic}"        tmp_zip = target_dir / f"TIC{tic}_allfiles.zip"        tmp_extract = target_dir / "tmp_extract"        if tmp_extract.exists():            shutil.rmtree(tmp_extract, ignore_errors=True)        ok = download_all_files_zip(tic, tmp_zip)        if not ok:            print(f"[ERROR] TIC {tic}: failed to download zip of files.")            continue        extract_zip(tmp_zip, tmp_extract)        allowed = set(spectra[name_col].astype(str).tolist())        kept = keep_only_selected_files(tmp_extract, allowed)        final_dir = target_dir / "Spectrum_fits"        if final_dir.exists():            shutil.rmtree(final_dir, ignore_errors=True)        final_dir.mkdir(parents=True, exist_ok=True)        for f in tmp_extract.rglob("*.fits"):            shutil.move(str(f), str(final_dir / f.name))        shutil.rmtree(tmp_extract, ignore_errors=True)        try:            tmp_zip.unlink()        except OSError:            pass        print(f"[OK] {target_name} --> TIC {tic}: saved {kept} Spectrum .fits in {final_dir}")if __name__ == "__main__":    main()